export const node=(id='start'):KnowledgeNode=>({id,title:id==='start'?'¿Sobre qué querés consultar?':'Requisitos de la consulta',text:id==='start'?'Elegí un tema o escribí una pregunta.':'Esta es la respuesta publicada en el documento de prueba.\n\nLa información no confirma una inscripción.',actions:id==='start'?[{code:'1',label:'Consultar requisitos',target:'requirements'}]:[{code:'9',label:'Volver al menú',target:'start'}],sources:[{...source,pages:[id==='start'?1:2]}],links:id==='start'?[]:[{id:'official-qa',label:'Referencia institucional',url:'https://example.org/informacion',review_after:'2099-01-01T00:00:00Z'}]});
